  transform: translateY(0);
}

.fullscreen #footer {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  transform: translateY(100%);
  transition: transform 0.2s ease-in-out;
  z-index: var(--z-modal);
}

